          /\ lpost RT Σ Σ' m m' sp lo /\ keepsL RT (rt_live RT Σ) Σ sp (rb2_fp pixs vs) m m'   (* [comment removed for export] *)
          /\ (pixs <> 0 -> pix1c (rt_live RT Σ') m' pixs vs cvs)
