          /\ (pixd <> 0 -> pix1c (rt_live RT Σ') m' pixd vd (mkCmapv 0 0 0 0) /\ p_cmap vd = 0 /\ p_w vd = p_w vs / 2 /\ p_h vd = p_h vs / 2
